css:
.button {
  color: #ecf0f1;
  font-size: 17px;
  background-color: #35ac50;
  border: 1px solid #3ecf5f;
  border-radius: 5px;
  cursor: pointer;
  padding: 10px;
  box-shadow: 0px 6px 0px #2b8f42;
  transition: all 0.1s;
}

.button:active {
  box-shadow: 0px 2px 0px #2b8f42;
  position: relative;
  top: 2px;
}
